/* ─── Dropdown toggle button ───────────────────────────────────────────────── */

.dropdownToggle {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0;
  font-size: 15px;
  font-weight: 500;
  color: #fff;
  background: none;
  border: none;
  cursor: pointer;
  font-family: 'Roobert PRO', Arial, sans-serif;
}

/* ─── Chevron icon inside toggle ────────────────────────────────────────────── */

.chevron {
  color: #21cfff;
  flex-shrink: 0;
  transition: transform 0.2s ease;
}

.chevronRotated {
  transform: rotate(180deg);
}

/* ─── Submenu container ─────────────────────────────────────────────────────── */

.submenu {
  display: flex;
