.submenuInner {
  display: flex;
  align-items: center;
}

.submenuLabel {
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.9);
  font-family: 'Roobert PRO', Arial, sans-serif;
}

/* ─── Coming Soon badge ──────────────────────────────────────────────────────── */

.comingSoonBadge {
