   ============================================================ */

/* Outer section wrapper */
.ctaSection {
  background-color: transparent;
  margin-bottom: 70px;
  padding: 0 5%;
  position: relative;
}

/* Inner card — navy background */
.ctaCard {
  background-color: #082753;
  background-image: url('/images/webflow/Union.svg');
  background-position: 100% 100%;
  background-repeat: no-repeat;
  background-size: auto;
  border-radius: 20px;
  padding: 40px 20px 50px;
  max-width: 1280px;
  margin: 0 auto;
  text-align: center;
}

/* Left-aligned variant */
.ctaCardLeft {
  text-align: left;
}

/* Content width cap (left layout only) */
.ctaContent {
  max-width: 700px;
}

/* Centered: no width cap */
.ctaContentCentered {
  max-width: none;
}

