/* Tooltip */
.tooltip {
  display: inline-block;
  position: relative;
  cursor: help;
}

.tooltip::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 80%;
  left: 50%;
  transform: translateX(-50%);
  background: #082753;
  color: #fff;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 12px;
  white-space: normal;
  opacity: 0;
  pointer-events: none;
  transition: 0.25s ease;
  z-index: 9999;
  width: 200px;
  text-align: center;
}

.tooltip:hover::after {
  opacity: 1;
  bottom: 90%;
}

.tooltip::before {
  content: '';
  position: absolute;
  bottom: 71%;
  left: 50%;
  transform: translateX(-50%);
  border: 6px solid transparent;
  border-top-color: #082753;
  opacity: 0;
  transition: 0.25s ease;
}

.tooltip:hover::before {
  opacity: 1;
}

.tooltipIco {
  width: 16px;
  height: 16px;
  opacity: 0.5;
}

