const bugs = require('fs').readFileSync('audit/sprints/sp-auto.jsonl','utf8')
  .split('\n').filter(Boolean).map(l => JSON.parse(l));

// Filter out false positives: rem=px equivalents, 'var()' fallback diffs, same values
const filtered = bugs.filter(b => {
  const t = b.title;
  // Skip if local and webflow resolve to same value
  if (t.includes('1rem') && t.includes('16px')) return false;
  if (t.includes('0.75rem') && t.includes('.75rem')) return false;  // same value different notation
  if (t.includes('var(--h2, 40px)') && t.includes('var(--h2)')) return false; // fallback = fine
  if (t.includes('1rem') && t.includes('var(--button-text)')) return false; // unknown resolution
  if (b.category === 'responsive') return true; // keep all responsive bugs
  // Keep P1 CSS bugs
  return b.severity === 'P1';
}).filter(b => {
  // Remove false 'font-size: 1rem vs 16px' type - same value
  const m = b.title.match(/local: (.+?), Webflow: (.+?)\"/);
  if (!m) return true;
  const [,local, wf] = m;
  // Normalize: 1rem=16px, .75rem=0.75rem etc
  const norm = v => v.replace(/^\./, '0.').replace('1rem', '16px').replace('0rem','0').trim();
  if (norm(local) === norm(wf)) return false;
  return true;
});

