  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 15px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.statBadgeText {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  text-align: left;
}

/* Video embed (.code-embed-3.how-code-embed.margin-top-50) */
.videoWrap {
  border-radius: 10px;
  width: 100%;
  max-width: 800px;
  margin: 50px auto 40px;
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.videoContainer {
  position: relative;
  height: 0;
  width: 100%;
  overflow: hidden;
  padding-bottom: calc(56.25% + 32px);
  border-radius: 10px;
}

/* CTA buttons */
.ctaRow {
  justify-content: center;
  align-items: center;
  margin-top: 1.5rem;
  display: flex;
  gap: 0;
  flex-wrap: wrap;
}

/* Primary: .a-gulf-book */
.btnPrimary {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: var(--shadow-card);
}

.btnPrimary:hover {
  background-color: var(--color-brand-navy);
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

/* Secondary: .navy-arrow-btn */
.btnSecondary {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-color: var(--color-text-primary);
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  margin-left: 1.25rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
}

.btnSecondary:hover {
  color: var(--color-brand-blue);
  background-color: var(--color-accent-bg-hover);
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .badgeGrid {
    max-width: 1000px;
  }

  .statBadge {
    padding: 20px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .statBadge {
    padding: 20px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .videoWrap {
    margin-top: 20px;
    margin-bottom: 20px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .badgeGridWrap {
    justify-content: center;
    align-items: center;
    display: flex;
  }

  .badgeGrid {
    grid-column-gap: 15px;
    grid-row-gap: 15px;
    grid-template-rows: auto;
    grid-template-columns: 1fr 1fr;
    grid-auto-columns: 1fr;
    display: grid;
    width: 100%;
  }

  .statBadge {
    width: 100%;
    padding-left: 20px;
    padding-right: 20px;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-top: 3rem;
    padding-bottom: 2rem;
  }

  .container {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .heading {
    font-size: 1.6rem;
    line-height: 1.25;
  }

  .subtitle {
    padding-left: 0;
    padding-right: 0;
  }

  .badgeGridWrap {
    flex-direction: column;
    padding-left: 0;
    padding-right: 0;
  }

  .badgeGrid {
    grid-column-gap: 10px;
    grid-row-gap: 10px;
    max-width: 100%;
    margin-bottom: 0;
  }

  .statBadge {
    flex-flow: column;
    width: 100%;
    align-items: center;
    padding: 10px;
  }

  .statBadgeText {
    text-align: center;
    font-size: 1rem;
    line-height: 16px;
  }

  .ctaRow {
    flex-direction: column;
    gap: 0.75rem;
  }

  .btnPrimary,
  .btnSecondary {
    background-color: var(--color-brand-blue);
    background-size: 29px 29px;
    flex-direction: column;
    width: 100%;
    margin-left: 0;
    font-size: 1.1rem;
  }
}

