.section {
  background-color: #0000;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.inner {
  text-align: center;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
}

/* Badge */
.badgeRow {
  justify-content: center;
  align-items: center;
  display: flex;
  margin-bottom: 1rem;
}

.badge {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  padding: 0 13px;
  line-height: 14px;
  display: inline-flex;
  align-items: center;
  margin-bottom: 17px;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 700;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  padding-top: 6px;
  padding-bottom: 6px;
}

/* Heading (.web-ban-title.mob-margin-less) */
.heading {
  color: var(--color-brand-navy);
  margin-top: 1.5rem;
  margin-bottom: 10px;
  padding: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 50px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

/* Subtitle (.h1-season-seeing.web-h1) */
.subtitle {
  color: var(--color-text-secondary);
  max-width: 53rem;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin-bottom: 0;
}

/* Stat badges (.web-job-attention + .web-ban-grid.mob-2grid) */
.badgeGridWrap {
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
}

.badgeGrid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex: 0 auto;
  width: auto;
  display: flex;
}

/* Individual badge box (.web-grid-box) */
.statBadge {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 15px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.statBadgeText {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  text-align: left;
}

/* Video embed (.code-embed-3.how-code-embed.margin-top-50) */
.videoWrap {
  border-radius: 10px;
  width: 100%;
  max-width: 800px;
  margin: 50px auto 40px;
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.videoContainer {
  position: relative;
  height: 0;
  width: 100%;
  overflow: hidden;
  padding-bottom: calc(56.25% + 32px);
  border-radius: 10px;
}

/* CTA buttons */
.ctaRow {
  justify-content: center;
  align-items: center;
  margin-top: 1.5rem;
  display: flex;
  gap: 0;
  flex-wrap: wrap;
}

/* Primary: .a-gulf-book */
.btnPrimary {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: var(--shadow-card);
}

.btnPrimary:hover {
  background-color: var(--color-brand-navy);
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

/* Secondary: .navy-arrow-btn */
.btnSecondary {
  color: #fff;
