  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  margin-bottom: 17px;
  padding: 0 13px;
  line-height: 14px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 700;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  padding-top: 6px;
  padding-bottom: 6px;
  margin: 0;
}

/* ── H1 ── */
.heading {
  color: var(--color-brand-navy);
  margin-top: 0;
  padding: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

/* ── Subtitle ── */
/* Matches .h1-season-seeing.our-work-banpara: max-width 52rem, font-size 16px, line-height 28px */
.subtitle {
  color: var(--color-text-secondary);
  max-width: 52rem;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  text-decoration: none;
}

/* ── Badge grid wrapper ── */
.badgeGridWrap {
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
}

/* ── Badge grid ── */
.badgeGrid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex: 0 auto;
  width: auto;
  display: flex;
}

/* ── Individual badge box ── */
.badgeBox {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 20px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.badgeIcon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.badgeText2 {
  color: var(--color-text-primary);
  text-align: left;
  margin-bottom: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .heading {
    color: var(--color-brand-navy);
    font-size: 40px;
    line-height: 1.25;
  }

  .subtitle {
    color: var(--color-text-secondary);
    margin-top: 10px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .subtitle {
    margin-top: 10px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .heading {
    color: var(--color-brand-navy);
    font-size: 40px;
    line-height: 1.25;
  }

  .subtitle {
    margin-top: 10px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 1.9rem;
    line-height: 1.25;
    margin-bottom: 10px;
  }

  .subtitle {
    font-size: 1.1rem;
  }

  .container {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }

  .badgeGrid {
    grid-column-gap: 15px;
    grid-row-gap: 15px;
    grid-template-columns: 1fr 1fr;
    display: grid;
    width: 100%;
  }

  .badgeBox {
    padding-left: 20px;
    padding-right: 20px;
    width: 100%;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-top: 3rem;
    padding-bottom: 2rem;
  }

  .container {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .heading {
    font-size: 1.9rem;
    line-height: 1.25;
  }

  .subtitle {
    text-align: center;
    padding-left: 0;
    padding-right: 0;
    font-size: 1rem;
  }

  .badgeGrid {
    grid-template-columns: 1fr 1fr;
    display: grid;
    width: 100%;
  }

  .badgeBox {
    flex-flow: column;
    width: 100%;
    align-items: center;
  }

  .badgeText2 {
    text-align: center;
    font-size: 1rem;
    line-height: 16px;
  }
}

