import re
css = open('boldteq-v1-0.webflow/css/boldteq-v1-0.webflow.css').read()
# Find heading-2 rules at key breakpoints 
blocks = re.findall(r'(@media[^{]+\{)((?:[^{}]*\{[^}]*\}[^{}]*)*)', css)
results = {}
for d, b in blocks:
    bps = re.findall(r'\d+px', d)
    if not bps: continue
    bp = bps[0]
    for m in re.finditer(r'\.[^\{]+\{[^\}]*\}', b):
        if '.heading-2 {' in m.group():
            results[bp] = m.group()[:120]
for k,v in sorted(results.items()):
    print(k, ':', v)
" 2>/dev/null

