import re
css = open('boldteq-v1-0.webflow/css/boldteq-v1-0.webflow.css').read()
blocks = re.findall(r'(@media[^{]+\{)((?:[^{}]*\{[^}]*\}[^{}]*)*)', css)
targets = ['heading-2.white', 'heading-2.how-work-sec3', 'heading-2.text-left.mission', 'heading-2.left']
for d, b in blocks:
    bps = re.findall(r'\d+px', d)
    if not bps: continue
    for t in targets:
        for m in re.finditer(r'\.[^\{]+\{[^\}]*\}', b):
            if t in m.group():
                print(f'{bps[0]}: {m.group()[:150]}')
" 2>/dev/null | head -30

