   ============================================================ */

.section {
  background-color: var(--color-text-primary);
  padding: 80px 5%;
}

.container {
  max-width: 1100px;
  margin-left: auto;
  margin-right: auto;
}

.inner {
  border: 1px solid rgba(33, 207, 255, 0.2);
  border-radius: 20px;
  padding: 56px 48px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 32px;
}

/* ── Text block ── */
.textBlock {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-width: 640px;
}

.heading {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 32px;
  font-weight: 700;
  line-height: 1.25;
  margin: 0;
}

.subtitle {
  color: rgba(255, 255, 255, 0.65);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  margin: 0;
}

