toolUseResult.originalFile:
/* ============================================================
   BlogHero — blog-hero.module.css
   Matches: .blog-page-banner on blog.html
   ============================================================ */

.section {
  background-color: transparent;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* Inner centering wrapper (.div-wrote-smoke.blogb-smoke) */
.inner {
  text-align: center;
  max-width: 45rem;
  margin-left: auto;
  margin-right: auto;
}

/* H1 (.blog-page-title) */
.heading {
  color: var(--color-brand-navy);
  margin-top: 0;
  padding: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

/* Subtitle (.h1-season-seeing.web-h1) */
.subtitle {
  color: var(--color-text-secondary);
  max-width: 53rem;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  text-decoration: none;
}

/* Badge grid wrapper (.web-job-attention) */
.badgeGridWrap {
  z-index: 1;
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
  position: relative;
}

/* Badge grid (.web-ban-grid.mob-2grid.blog-ban-grid) — 3 boxes in a row */
.badgeGrid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex: 0 auto;
  width: auto;
  display: flex;
}

/* Individual badge box (.blog-ban-gridbox) */
.badge {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 15px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.badgeIcon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.badgeLabel {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  text-align: left;
  margin: 0;
}

/* CTA button (.div-job-attention > .a-gulf-book) */
.ctaWrap {
  z-index: 1;
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  display: flex;
  position: relative;
}

.cta {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  background-image: url('/images/webflow/Group-46729-2.svg'),
    linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  display: inline-flex;
  box-shadow: var(--shadow-card);
  transition: background-color 0.2s;
}

.cta:hover {
  background-color: var(--color-brand-navy);
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .heading {
    color: var(--color-brand-navy);
    font-size: 40px;
    line-height: 1.25;
  }

  .subtitle {
    margin-top: 10px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .heading {
    font-size: 2.5rem;
    line-height: 1.25;
    margin-bottom: 10px;
  }

  .badgeGrid {
    flex-wrap: wrap;
    justify-content: center;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 1.9rem;
  }

  .badgeGrid {
    grid-column-gap: 15px;
    grid-row-gap: 15px;
    grid-template-columns: 1fr 1fr;
    display: grid;
    width: 100%;
  }

  .badge {
    width: 100%;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-top: 3rem;
    padding-bottom: 2.5rem;
  }

