}

/* ==========================================================
   works-sec  (Webflow: .works-sec)
   ========================================================== */
.worksSec {
  background-color: transparent;
  padding: 20px 5% 60px;
  position: relative;
}

/* ==========================================================
   Container  (Webflow: .container-large-3)
   ========================================================== */
.containerLarge3 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* ==========================================================
   Badge row  (Webflow: .benefit-subhead-out / .benefitsubott)
   ========================================================== */
.benefitSubheadOut {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  justify-content: center;
  align-items: center;
  display: flex;
}

.benefitsubott {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  margin-bottom: 0;
