  line-height: 14px;
}

/* ==========================================================
   Gradient text  (Webflow: .faq-sky-text)
   ========================================================== */
.faqSkyText {
  color: var(--color-brand-cyan);
  text-transform: capitalize;
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  font-weight: 500;
}

/* ==========================================================
   Section heading  (Webflow: .heading-2.margin-bottom-24px)
   ========================================================== */
.heading2 {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  text-align: center;
  line-height: 45px;
  margin-bottom: 20px;
}

/* ==========================================================
   Body copy  (Webflow: .paragraph.center)
   ========================================================== */
.paragraph {
  color: var(--color-text-secondary);
  font-size: 16px;
  line-height: 28px;
  text-align: center;
  margin-bottom: 0;
}

/* ==========================================================
   Grid  (Webflow: .feature-grid.margin-top-40px.hiring-slider)
   Webflow uses Slick with slidesToShow: 3 at desktop — only 3 cards
   visible at a time (1 row), paginating via dots. We replicate with
   CSS horizontal scroll-snap so all 6 cards stay in the DOM but only
   3 are visible at once, matching the Webflow section height.
   ========================================================== */
.featureGrid {
  display: flex;
  flex-direction: row;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  gap: 20px;
  margin-top: 40px;
  scrollbar-width: none;
}

.featureGrid::-webkit-scrollbar {
  display: none;
}

/* ==========================================================
   Card  (Webflow: .feature-card.space-between)
   At desktop: flex child sized to 1/3 of container (minus gaps)
   so exactly 3 cards are visible at once, matching Slick slidesToShow:3
   ========================================================== */
.featureCard {
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  text-align: center;
  mix-blend-mode: normal;
  background-color: var(--color-success-bg);
  background-image: none;
  border: 1px solid #009ce0;
  border-radius: 20px;
  flex-flow: column;
  justify-content: space-between;
  align-items: center;
  padding: 25px 17px 17px;
  text-decoration: none;
  display: flex;
  /* Desktop: show 3 cards at once (gap: 20px × 2 = 40px total) */
  flex: 0 0 calc(33.333% - 14px);
  min-width: calc(33.333% - 14px);
  scroll-snap-align: start;
}

.featureCard:hover {
  background-color: var(--color-brand-card-hover);
  border-color: var(--color-brand-card-border);
}

/* ==========================================================
   Text wrapper  (Webflow: .text-wrapper)
   ========================================================== */
.textWrapper {
  margin-bottom: 20px;
}

/* ==========================================================
   Card title  (Webflow: .subheading-large)
   ========================================================== */
.subheadingLarge {
  color: var(--color-text-primary);
  letter-spacing: -0.02em;
  margin-bottom: 10px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 25px;
}

/* ==========================================================
   Card body copy  (Webflow: .paragraph-small-2.margin-bottom-20px.grid-wrap)
   ========================================================== */
.paragraphSmall2 {
  color: var(--color-text-secondary);
  min-height: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  letter-spacing: -0.08px;
  margin-bottom: 0;
  line-height: 28px;
  max-width: 315px;
}

/* ==========================================================
   Card image  (Webflow: .full-width-image.drop-shadow.blue-shadow)
   ========================================================== */
.fullWidthImage {
  display: block;
  width: 100%;
  height: auto;
  filter: drop-shadow(0px 0px 30px rgba(0, 126, 188, 0.1));
}

/* ==========================================================
   Dots navigation (replaces Slick dots)
   Webflow Slick dots: display flex, center, gap 10px, margin-top 50px
   ========================================================== */
.sliderDots {
  display: flex;
  justify-content: center;
  gap: 10px;
  list-style: none;
  margin: 50px 0 0;
  padding: 0;
}

.sliderDot {
  /* Visual 12×12 circle; tap area expanded to 24×24 via padding for WCAG 2.5.8.
     background-clip: content-box keeps the colored circle at 12×12 — the
     padding area is transparent so the visual dot does not change. */
  background: transparent;
  border: 1px solid #d1d1d1;
  border-radius: 20px;
  width: 12px;
  height: 12px;
  padding: 6px;
  box-sizing: content-box;
  background-clip: content-box;
  cursor: pointer;
  transition: background-image 0.2s ease;
}

.sliderDot.active {
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  background-clip: content-box;
  border-color: transparent;
}

/* ==========================================================
   @media (min-width: 1280px)
   Webflow line 21922: .feature-card → bg/border (unchanged)
   Webflow line 21927: .feature-card.space-between → pl/pr 20px
   Webflow line 21944: .subheading-large → 25px / 32px
   Webflow line 21932: .container-large-3 → max-width 1280px
   ========================================================== */
@media screen and (min-width: 1280px) {
  .featureCard {
    background-color: var(--color-success-bg);
    border-color: var(--color-brand-card-border);
    padding-left: 20px;
    padding-right: 20px;
  }

  .containerLarge3 {
    max-width: 1280px;
  }

  .paragraphSmall2 {
    max-width: 308px;
  }

  .subheadingLarge {
    font-size: 25px;
    line-height: 32px;
  }
}

/* ==========================================================
   @media (min-width: 1440px)
   Webflow line 23357 — .feature-card.space-between gets pl/pr 25px
   container-large-3 gets max-width: 1320px
   ========================================================== */
@media screen and (min-width: 1440px) {
  .featureCard {
    background-color: var(--color-success-bg);
    background-image: none;
    border-color: var(--color-brand-card-border);
    justify-content: space-between;
    align-items: center;
    padding-left: 25px;
    padding-right: 25px;
  }

  .containerLarge3 {
    max-width: 1320px;
  }

  .paragraphSmall2 {
    max-width: 308px;
    margin-left: auto;
    margin-right: auto;
  }
}

/* ==========================================================
   @media (max-width: 991px)
   Webflow: Slick breakpoint 980px → slidesToShow: 2. We show 2 cards
   at once in the horizontal scroll carousel.
   ========================================================== */
@media screen and (max-width: 991px) {
  .featureCard {
    /* Show 2 cards at once at tablet (Slick slidesToShow: 2 at <980px) */
    flex: 0 0 calc(50% - 10px);
    min-width: calc(50% - 10px);
  }

  .paragraphSmall2 {
    max-width: none;
  }

  .heading2 {
    font-size: 35px;
    line-height: 45px;
  }
}

/* ==========================================================
   @media (max-width: 767px)
   Webflow line 27051: .feature-grid.margin-top-40px → 1 col (plain grid)
   Webflow line 27055: .feature-grid.margin-top-40px.hiring-slider → 20px gap
     (Slick still controls layout here — still shows 2 at breakpoint 980)
   Webflow line 27177: .works-sec → padding-top: 0; padding-bottom: 50px
   ========================================================== */
@media screen and (max-width: 767px) {
  .worksSec {
    padding-top: 0;
    padding-bottom: 50px;
  }

  .featureGrid {
    gap: 20px;
    margin-top: 20px;
  }

  .featureCard {
    /* Slick is still in slidesToShow:2 mode at this width (breakpoint is 480px) */
    flex: 0 0 calc(50% - 10px);
    min-width: calc(50% - 10px);
    padding-left: 18px;
    padding-right: 18px;
  }

  .paragraphSmall2 {
    text-align: center;
    max-width: none;
  }

  .subheadingLarge {
    text-align: center;
  }

  .heading2 {
    font-size: 34px;
    line-height: 28px;
    margin-bottom: 10px;
    text-align: center;
  }

  .textWrapper {
    text-align: center;
  }
}

/* ==========================================================
   @media (max-width: 479px)
   Webflow line 29597: .feature-grid.margin-top-40px.hiring-slider → margin-top: 20px, 20px gap
   Webflow line 29603: .feature-card → padding: 24px
   Webflow line 29607: .feature-card.space-between → pl/pr 18px
   Slick breakpoint 480px → slidesToShow: 1 — show 1 card at a time
   ========================================================== */
@media screen and (max-width: 479px) {
  .heading2 {
    font-size: 21px;
    line-height: 28px;
    text-align: center;
