    gap: 20px;
  }

  .featureCard {
    flex: 0 0 100%;
    min-width: 100%;
    padding: 24px 18px;
  }

  .paragraphSmall2 {
    text-align: center;
    max-width: none;
  }

  .subheadingLarge {
    text-align: center;
  }
}

