/* ============================================================
   PortfolioPopup — matches Webflow .global-popup exactly
   ============================================================ */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 999999;
  background-color: rgba(15, 23, 42, 0.65);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Full-content mode container */
.container {
  position: relative;
  background-color: #fff;
  border-radius: 24px;
  width: 100%;
  max-width: 1280px;
  min-height: 600px;
  max-height: 600px;
  display: grid;
  grid-template-rows: auto;
  grid-template-columns: 1fr;
  animation: slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  margin-left: auto;
  margin-right: auto;
  flex: 1;
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Gallery mode — narrower */
.containerGallery {
  max-width: 600px;
  min-height: auto;
  max-height: 85vh;
}

/* Close button */
.closeBtn {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 11;
  display: flex;
  align-items: center;
  justify-content: center;

