/* ============================================================
   AGENCY FIT — agency-fit.module.css
   Matches: .how-work-sec2.overflow-hidden on how-it-works.html
   ============================================================ */

.section {
  background-color: transparent;
  padding: 0 5% 70px;
  position: relative;
  overflow: hidden;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* Header (.demo-sec2-outer > .demo-cont-center > .column-regular.column-left.web-max) */
.header {
  text-align: center;
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 40px;
}

.heading {
  color: var(--color-brand-navy);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 48px;
  margin-top: 0;
  margin-bottom: 16px;
}

.subtitle {
  color: var(--color-text-secondary);
  text-align: center;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin: 0;
}

/* Cards grid (.how-works-gridboxes) */
.grid {
  display: grid;
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
}

/* Individual card (.demodev-sec2-grid-inner) */
.card {
  background-color: var(--color-success-bg);
  border: 1px solid #009ce0;
  border-radius: 20px;
  flex-flow: column;
  justify-content: flex-start;
  align-items: flex-start;
  padding: 22px;
  display: flex;
  position: relative;
}

/* Icon (.demo2-icon) */
.cardIcon {
  display: block;
  margin-bottom: 12px;
}

.cardTitle {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 25px;
  margin-top: 0;
  margin-bottom: 7px;
  text-align: left;
}

.cardText {
  color: var(--color-text-secondary);
  text-align: left;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin: 0;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .section {
    padding-bottom: 70px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .section {
    padding-bottom: 70px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding-bottom: 60px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section {
    padding-bottom: 60px;
